Import ListNotations.
Open Scope bv_scope.
Import ITree.Exc.

(* [comment removed for export] *)
(* [comment removed for export] *)
(* [comment removed for export] *)
Definition PATEXIT : Z := 0x21814.        (* [comment removed for export] *)
Definition PATX : Z := 0x5b8e8.           (* [comment removed for export] *)
Definition PATX_CALLFN : Z := 0x218d8.    (* [comment removed for export] *)
Definition PNEED_LOCKS : Z := 0x5bb33.    (* [comment removed for export] *)
Definition PATEXIT_STACK : Z := 48.
(* [comment removed for export] *)
Definition PEXIT_GUARD : Z := 0x131c8.    (* [comment removed for export] *)
Definition PAEF_INCB : Z := 0x3b7a4.      (* [comment removed for export] *)

(* [comment removed for export] *)
Definition atx_cells (head slot f0 a0 : Z) (m : word -> option byte) : Prop :=
  rw_cells usegs m 0x5b8e8 [C1 (Z_to_bv 8 0)]
  /\ rw_cells usegs m (0x5b8ec) [C4 (Z_to_bv 64 0)]
  /\ rw_cells usegs m (0x5b8f0) [C4 (Z_to_bv 64 slot)]
  /\ rw_cells usegs m (0x5b8f8) [C8 (Z_to_bv 64 head)]
  /\ rw_cells usegs m (0x5b900) [C8 (Z_to_bv 64 0)]
  /\ rw_cells usegs m (0x5b908) [C8 (Z_to_bv 64 f0)]
  /\ rw_cells usegs m (0x5ba08) [C8 (Z_to_bv 64 a0)].

(* [comment removed for export] *)
Definition atx_state (reg : bool) (m : word -> option byte) : Prop :=
  atx_cells (if reg then 0x5b900 else 0) (if reg then 1 else 0) (if reg then PATX_CALLFN else 0) (if reg then PEXIT_GUARD else 0) m
  /\ rw_cells usegs m PAEF_INCB [C1 (Z_to_bv 8 0)].

(* [comment removed for export] *)
Definition atx_addr (a : Z) : Prop :=
  (0x5b8e8 <= a < 0x5b8e9)%Z \/ (0x5b8ec <= a < 0x5b8f4)%Z \/ (0x5b8f8 <= a < 0x5b910)%Z \/ (0x5ba08 <= a < 0x5ba10)%Z.

Definition atx_state_addr (a : Z) : Prop := atx_addr a \/ (PAEF_INCB <= a < PAEF_INCB + 1)%Z.

Lemma atx_cells_agree : forall (P : Z -> Prop) m m' head slot f0 a0,
  magree usegs P m m' -> (forall a, atx_addr a -> P a) -> atx_cells head slot f0 a0 m -> atx_cells head slot f0 a0 m'.
Proof.
